import{_ as e,k as t,v as n}from"./app-Xgp6P-Ux.js";import{t as r}from"./plugin-vue_export-helper-BDNMzG2s.js";import"./gzh-BO4QB3XE.js";import"./zsxq-BKcsYlFO.js";var i=JSON.parse(`{"path":"/column/%E6%95%B0%E6%8D%AE%E5%88%86%E6%9E%90%E6%80%9D%E7%BB%B4%E4%B8%8E%E5%AE%9E%E6%88%9823%E8%AE%B2/24.html","title":"23-时间管理：优秀的数据分析师如何做时间管理？","lang":"zh-CN","frontmatter":{"title":"23-时间管理：优秀的数据分析师如何做时间管理？","icon":"blog","date":"2025-09-26T15:16:47.000Z","author":"bornforthis","isOriginal":true,"sticky":false,"star":false,"article":true,"timeline":true,"image":false,"navbar":true,"sidebarIcon":true,"comment":true,"lastUpdated":true,"editLink":true,"backToTop":true,"toc":true,"description":"你好，我是悦创。 前面讲了很多的方法论，这一节课我来说时间管理。因为很多思维，很多产品到最后落地的时候，还是要看时间管理。我自身对时间管理体会也非常深，现在就跟你聊一聊。 本课时分为三部分内容： 职场时间管理方法论； 职场时间管理的关键点； 职场时间管理感触； 1. 职场时间管理方法论 先看我的一个案例，这是我在高中、大学的时间安排。 从星期一排到星期...","head":[["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"23-时间管理：优秀的数据分析师如何做时间管理？\\",\\"image\\":[\\"https://bornforthis.cn/gzh.jpg\\",\\"https://bornforthis.cn/zsxq.jpg\\"],\\"datePublished\\":\\"2025-09-26T15:16:47.000Z\\",\\"dateModified\\":\\"2025-09-26T10:39:15.000Z\\",\\"author\\":[{\\"@type\\":\\"Person\\",\\"name\\":\\"bornforthis\\"}]}"],["meta",{"property":"og:url","content":"https://bornforthis.cn/column/%E6%95%B0%E6%8D%AE%E5%88%86%E6%9E%90%E6%80%9D%E7%BB%B4%E4%B8%8E%E5%AE%9E%E6%88%9823%E8%AE%B2/24.html"}],["meta",{"property":"og:site_name","content":"AI悦创-Python一对一辅导"}],["meta",{"property":"og:title","content":"23-时间管理：优秀的数据分析师如何做时间管理？"}],["meta",{"property":"og:description","content":"你好，我是悦创。 前面讲了很多的方法论，这一节课我来说时间管理。因为很多思维，很多产品到最后落地的时候，还是要看时间管理。我自身对时间管理体会也非常深，现在就跟你聊一聊。 本课时分为三部分内容： 职场时间管理方法论； 职场时间管理的关键点； 职场时间管理感触； 1. 职场时间管理方法论 先看我的一个案例，这是我在高中、大学的时间安排。 从星期一排到星期..."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:image","content":"https://bornforthis.cn/gzh.jpg"}],["meta",{"property":"og:locale","content":"zh-CN"}],["meta",{"property":"og:updated_time","content":"2025-09-26T10:39:15.000Z"}],["meta",{"property":"article:author","content":"bornforthis"}],["meta",{"property":"article:published_time","content":"2025-09-26T15:16:47.000Z"}],["meta",{"property":"article:modified_time","content":"2025-09-26T10:39:15.000Z"}]]},"git":{"createdTime":1669634625000,"updatedTime":1758883155000,"contributors":[{"name":"AndersonHJB","username":"AndersonHJB","email":"cleland1432803776@icloud.com","commits":13,"url":"https://github.com/AndersonHJB"},{"name":"AI悦创","username":"","email":"cleland1432803776@icloud.com","commits":1}],"changelog":[{"hash":"a85fbe37c1ce7d858817d2f4a53d549f24af243f","time":1758883155000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"docs: 更新数据分析和实现23讲专栏中的24章内容"},{"hash":"c0053c46b0dbb9a974e4f6f4e26750ca1a9dde31","time":1758882441000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"docs: 添加数据分析课程文档和图片资源"},{"hash":"1bf8ef0014b4b72bca7eebd749390f306fe02ab5","time":1758803033000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"docs: 添加数据分析课程相关图片和更新文章内容"},{"hash":"17ef58c9cdcab06b93afdb348f078c3cf624d807","time":1758797317000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"docs: 添加图片资源并更新文档内容"},{"hash":"a44f645ebd9aae658b7cb10f6cb11490fddfdb0c","time":1752398759000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"docs(食谱): 更新澄面版本说明并添加鸡蛋灌饼和手抓饼文档"},{"hash":"70353fead4a0a1bfadb60ece94c0f3a9f80bfc08","time":1746926862000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"更新文件夹名称"},{"hash":"ae8a442bae9aa264fee20e42267291df3a74b667","time":1746879162000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"更新食谱文档，优化标签和步骤格式"},{"hash":"9bfdcd8407ca12cf09f385c602eb1c60cc5f3c56","time":1745906987000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"新增 Vuepress 侧边栏自定义文档，包含自动生成侧边栏的说明及相关信息"},{"hash":"4d098f34b968c7f9162e7d143141d46669c76d6e","time":1745325668000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"Add articles on programming and cooking: \\"Can computer programs really kill people?\\" and \\"清蒸鲈鱼\\""},{"hash":"1c35a6532eb53bd6ed2f2afd6f70564646e80c01","time":1744328990000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"去掉head"},{"hash":"cbb3a0f217ea57089ad27386b3127e612324b609","time":1675049774000,"email":"cleland1432803776@icloud.com","author":"AI悦创","message":"update"},{"hash":"76989bb701c8ac79bbc7e2e46050c8b08855befd","time":1670605630000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"update"},{"hash":"86c50aa64ad737c1db38d74dbb5ec22bb6c5bbeb","time":1670575429000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"update"},{"hash":"027da62f7fafa8a29d6f7ba006e9bff7ac22acfe","time":1669634625000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"first commit"}]},"readingTime":{"minutes":12.23,"words":3668},"filePathRelative":"column/数据分析思维与实战23讲/24.md","excerpt":"<p>你好，我是悦创。</p>\\n<p>前面讲了很多的方法论，这一节课我来说时间管理。因为很多思维，很多产品到最后落地的时候，还是要看时间管理。我自身对时间管理体会也非常深，现在就跟你聊一聊。</p>\\n<p>本课时分为三部分内容：</p>\\n<ul>\\n<li>\\n<p>职场时间管理方法论；</p>\\n</li>\\n<li>\\n<p>职场时间管理的关键点；</p>\\n</li>\\n<li>\\n<p>职场时间管理感触；</p>\\n</li>\\n</ul>\\n<h2>1. 职场时间管理方法论</h2>\\n<p>先看我的一个案例，这是我在高中、大学的时间安排。</p>\\n<figure><figcaption></figcaption></figure>","copyright":{"author":"bornforthis"},"autoDesc":true}`),a={name:`24.md`};function o(r,i,a,o,s,c){return t(),e(`div`,null,[...i[0]||=[n(`<p>你好，我是悦创。</p><p>前面讲了很多的方法论，这一节课我来说时间管理。因为很多思维，很多产品到最后落地的时候，还是要看时间管理。我自身对时间管理体会也非常深，现在就跟你聊一聊。</p><p>本课时分为三部分内容：</p><ul><li><p>职场时间管理方法论；</p></li><li><p>职场时间管理的关键点；</p></li><li><p>职场时间管理感触；</p></li></ul><h2 id="_1-职场时间管理方法论" tabindex="-1"><a class="header-anchor" href="#_1-职场时间管理方法论"><span>1. 职场时间管理方法论</span></a></h2><p>先看我的一个案例，这是我在高中、大学的时间安排。</p><figure><img src="/assets/CgqCHl86aI2AV2hRAABZI0ifnUg626-BbDL1i-t.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>从星期一排到星期天，从早上 6:00 排到晚上 11:00。我读书的时候就这么排时间，很多人都觉得这样非常紧凑，效果也不会差很多吧。其实这样的效果真的很一般，因为它有点违背人性。它首先要求一个人的自律性极强，而 90% 的人实际上是做不到的。除了自律性之外，还需要你保持专注性，比如早上 6:00-8:00，你做 A 事情，你还要把它做完不能拖。同时这是一个非常持续的过程。它确实没有考虑到人性，人都是有七情六欲的，也有状态好和状态不好的时候，所以我非常不建议你用这种时间管理方法。</p><p>后来，我在时间管理这一块并没有刻意去看过什么书，纯粹就是凭自己摸索。时间还是那些时间，但是在做事的时候，会有一些原则，也就是所谓的方法论。</p><ul><li><p>事情优先级排序：二八原则</p></li><li><p>状态好的时候做最重要的事，状态不好的时候做杂事：以人为本</p></li><li><p>对最重要的事情进行效果反馈并反思：刻意练习</p></li><li><p>有点可控的小压力：有压力会更高效更聪明</p></li></ul><p>首先事情一定是有优先级排序的，也就是说会有二八原则。当我把 20% 的高优事情做完之后，基本上就解决了 80% 的问题。工作中的每一天，可能真的有很多事，但是我一定会找到那个高优先级的事情。道理其实大家都懂，只不过在这个过程中，你有没有真的这样去做。</p><p>第二就是状态好的时候做最重要的事情，状态不好的时候做杂事（不重要的事情）。一定是以人为本，而不是以事为本。你今天状态好，你甚至通宵达旦地干都没有问题。如果你状态不好，你最好一天都不要碰那些最重要的事情，当你状态好了之后你再去碰。同时也不能不做事，比如可以跟产品业务聊聊天，这都是比较好的方式。这个能力也非常重要——当你状态不好的时候，你怎么样让自己兴奋起来。</p><p>第三就是对最重要的事情进行效果反馈并反思，这就是一个刻意练习的过程。当我们做完重要的事情，并不是做完就做完了，一定要有反馈，同时还要反思。为什么很多人是低质量的勤奋，就是在于这个点，很多人始终在自己的思维圈里面没有得到别人的反馈，或者说得到了反馈之后也不进行反思，不进行优化。</p><p>第四，一定要有可控的小压力，因为有压力才会更高效、更聪明。大家可以去感受一下，你到底是周一更聪明还是周五更聪明？</p><p>综合举个例子，比如说某一天有开会、发邮件、提数、专题分析以及跟 leader 汇报等工作。事情很多，到底哪个更重要呢？其实评判标准就是，做完哪一件事对你接下来一段时间的发展最有好处，那这件事就是你的高优先级。当然除了那种必须要做的，比如说管理层突然有临时事件。</p><p>比如写专题分析，你觉得最重要。那当你做完专题分析后，得到的效果是什么，影响力有没有增加，你的团队协作有没有变好？有没有一些落地点？如果在这过程中发现没什么变化。那可能就是你选错了或者说这件事你压根就没有做好。</p><h2 id="_2-职场时间管理的关键点" tabindex="-1"><a class="header-anchor" href="#_2-职场时间管理的关键点"><span>2. 职场时间管理的关键点</span></a></h2><p>接下来就是在职场当中时间管理的一些关键点，这也是我个人的经历。</p><h3 id="_2-1-1-早起" tabindex="-1"><a class="header-anchor" href="#_2-1-1-早起"><span>2.1 （1）早起</span></a></h3><p>早起的好处有很多，比如：</p><ul><li><p>一天做的事情明显比往常更多</p><p>你早上 6:00 跟早上 7:00 起来，或者说早上 7:00 跟早上 8:00 起来，这绝对是两个概念。不要小看这一个小时或半个小时，非常关键。</p></li><li><p>心情更好，身体更好</p><p>可能因为你迟到或者晚起了半个小时，那么后面所有的事情都已经发生变化了。因为你所有的事情都会变得很紧凑，这实际上对你个人的神经是不太好的。</p></li><li><p>运气更好</p><p>跟你分享一个例子，实际上大部分管理者，他们都是很早到公司的。如果你到公司也比较早的话，久而久之，他对你的印象会相对来说深一点。这样无论是通过私下还是休闲时交流。他对你的印象都会明显好一点，运气也会更好。</p></li><li><p>周一早上不虚，周末两天充实</p><p>像我在刚毕业的时候，工作的前 3 年就怕周一早上，因为周一早上经常要开会。而我是从周六日那样一种娱乐的状态切换到工作的状态，它有一个真空期。一旦我在周六日早起，周一也早起，我完全可以把很多杂事处理完毕，也会为工作做好准备，周末这两天也会过得很充实。</p><p>每天 30 分钟的价值是巨大的，不同时间段的时间价值不一样，比如早上 6:30-7:00 这半个小时跟下午 5:30-6:00 下班前的半小时，在时间利用、时间效率方面肯定不一样。</p></li></ul><h3 id="_2-2-2-阶段性熬夜" tabindex="-1"><a class="header-anchor" href="#_2-2-2-阶段性熬夜"><span>2.2 （2）阶段性熬夜</span></a></h3><p>熬夜这件事是必须要谈的，熬夜一定要有价值。假设接下来的这段时间对你的发展很重要，这个时候就要投入大量时间去做这件事，所以一定会有一个阶段性熬夜。</p><p>我们可以这样去理解这件事，当一个产品在前期尝试，比如说小流量的时候发现效果很不错，那接下来应该投入大量的资源去推广这个产品。包括一个人，每年不同时间段（3月、5月、6月）的重要程度不一样，那你就要去评估哪一段时间要重点发力，所以肯定会有一个熬夜的过程。</p><p>其实熬夜也是有些好处的，比如：</p><ul><li><p>熬夜可以证明你比较年轻，因为你还能熬的动夜；</p></li><li><p>生活不能太常规化，偶尔要熬下夜打破这种平静；</p></li><li><p>熬夜本身就代表了一种压力，压力会让你前进；</p></li><li><p>夜深人静的时候，你的内心会变得很平静，可能会冒出一些比较“亮”的想法，或者看待事物又有一个不一样的角度。</p></li></ul><h3 id="_2-3-3-上下班时间" tabindex="-1"><a class="header-anchor" href="#_2-3-3-上下班时间"><span>2.3 （3）上下班时间</span></a></h3><p>其实一二线城市的上下班时间有很多，比如说 90分钟（上班 45 分钟，下班 45 分钟）。每个人应该给自己定一个最低目标。</p><p>我这边的最低目标：一周内要保证有 3 天学习，你必须要花这段时间，如果你什么都不做，那这段时间相当于就没了。</p><p>做什么呢？我个人建议就是做跟自己职业规划相结合的事情，让自己在其他方面多充充电，不要花过多时间去做纯工作上的事情。如果确实不知道做啥，看书是最好的打发方式。在前期可以看经济类、管理类、心理学类、文学类的书，小说肯定不能看。</p><p>尽量不要开车上下班，能打车就打车，能坐公交坐地铁就坐公交坐地铁。如果你开车，上下班这段时间就干不了什么，而且一堵车，你也很会很闹心，影响后续工作。</p><h3 id="_2-4-4-会议时间" tabindex="-1"><a class="header-anchor" href="#_2-4-4-会议时间"><span>2.4 （4）会议时间</span></a></h3><p>公司会议时间很多，在会议前一定要先了解这个会议有什么主题，想解决什么问题，有哪些人参与？如果跟你自身没什么关系，就找个借口不要去。</p><p>其实会议时间有三个关键点：</p><ul><li><p>个人汇报——必须</p></li><li><p>信息的同步和了解——知道方向</p></li><li><p>管理层的思考方式——学习他人的思维</p></li></ul><p>第一个就是个人汇报，这是必须要参加的，因为需要你本人做汇报，自己也会成长。</p><p>第二个就是信息的同步和了解，你要知道其他人是怎么想的，知道一些未来的业务方向。</p><p>第三个，我个人认为是价值最大的。无论是你个人汇报还是别人汇报，管理人一定会进行一些点评，他们会提一些意见。那么在这个过程中，我们一定要去看管理层的思考方式。你一定要相信他们能做到管理层，他们的思维一定在某一方面比你厉害，所以学习他人的思维，他是怎么想的。特别是当你写一个专题分析的时候，对方给你一些建议，这个时候你一定要认真听。当然这过程中可能有一些不合理的，但大部分时候都是合理的。你一定要知道为什么管理层能想到这个点，为什么你就没有想到？知道哪一块不足，然后去弥补。这个时候你的提升是最快的。</p><h3 id="_2-5-5-周六日" tabindex="-1"><a class="header-anchor" href="#_2-5-5-周六日"><span>2.5 （5）周六日</span></a></h3><p>周六日要做到学习跟娱乐的平衡，或者说是工作跟娱乐的平衡。很多同学到周六日可能喜欢睡懒觉。其实你每个周末少睡一个小时，稍微学习一下，一个小时或者半个小时也好，这证明你自己是在独立思考的。</p><p>再说娱乐，周六日我们一定要进行娱乐吗？这个是肯定要的，一定要进行放松。</p><p>我个人的建议就是户外运动，尽量不要打游戏、在家躺着、看电视，因为越玩越累。尽量去户外运动运动，打打球，去公园里面走走，这都非常好。在这个过程中，很多时候你的思维时候就能打开，往往会想到很多亮点。</p><p>一旦你在周六日进行了学习，下周的工作也会变得更加自信，状态会非常好。同时作为数据分析师，独自去研究一些专题，也只有周末时间能满足你。</p><h2 id="_3-职场时间管理感触" tabindex="-1"><a class="header-anchor" href="#_3-职场时间管理感触"><span>3. 职场时间管理感触</span></a></h2><p>前面说了 5 个关键点，有些同学可能会觉得从早起到上下班和周末都安排上了学习，觉得非常累。但我个人对职场时间管理的感触是这样的：</p><ul><li><p>不是工作太辛苦，而是我们越来越懒</p><p>你有空的时候可以在早上 6:30 去坐公交，你会发现全是学生。想想自己高中读书的时候是不是也很早就起来，不是自己做不到，而是真的有变懒。我上述说的几个关键点，也不是非逼你做到，比如你今天心情不好，还要让你周末或地铁上去思考一些深度的问题吗？不用，你这段时间完全可以选择发呆，但是保持学习的稳定性很重要。</p></li><li><p>兴趣是伪命题，工匠精神才是源动力</p><p>我个人很喜欢当老师，在做这门课的时候，由于私人原因，有几次课非常难受，进度有些拖。但是不行，我一直都提醒自己，一定要保持每周更新一课时或者两课时的频率，就算自己遇到了难事，也要坚持。更多的时候工匠精神才是源动力，这涉及责任及耐心。</p></li></ul><h2 id="_4-总结" tabindex="-1"><a class="header-anchor" href="#_4-总结"><span>4. 总结</span></a></h2><p>今天我根据我自身的经历及摸索，讲述了时间管理的方法论，比如二八法则、以人为本、定期复盘反馈，给自己一些压力等。然后分享了些时间管理的关键点，比如：早起、阶段性熬夜、利用好上下班时间和会议时间以及周末时间。</p><p>你可以选择适合自己的方法合理安排自己的时间，最重要的是要去实施，一定要去做。坚持一段时间你就会有质的飞跃，你也一定会来感谢我，这跟减肥成功一样的道理。</p><p>你有什么其他的时间管理的好办法吗？可以在下方留言与大家讨论。如果没有，也可以说些关于时间管理的小故事。</p><details class="hint-container details"><summary>公众号：AI悦创【二维码】</summary><figure><img src="/gzh.jpg" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure></details><div class="hint-container info"><p class="hint-container-title">AI悦创·编程一对一</p><p>AI悦创·推出辅导班啦，包括「Python 语言辅导班、C++ 辅导班、java 辅导班、算法/数据结构辅导班、少儿编程、pygame 游戏开发、Web、Linux」，招收学员面向国内外，国外占 80%。全部都是一对一教学：一对一辅导 + 一对一答疑 + 布置作业 + 项目实践等。当然，还有线下线上摄影课程、Photoshop、Premiere 一对一教学、QQ、微信在线，随时响应！微信：Jiabcdefh</p><p>C++ 信息奥赛题解，长期更新！长期招收一对一中小学信息奥赛集训，莆田、厦门地区有机会线下上门，其他地区线上。微信：Jiabcdefh</p><p>方法一：<a href="http://wpa.qq.com/msgrd?v=3&amp;uin=1432803776&amp;site=qq&amp;menu=yes" target="_blank" rel="noopener noreferrer">QQ</a></p><p>方法二：微信：Jiabcdefh</p></div><figure><img src="/zsxq.jpg" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure>`,53)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};